// Rocq: Corelib.Numbers.Cyclic.Int63.PrimInt63.ltb
// Variant: uncurried
pub fn ltb(v0: u64, v1: u64) -> bool {
  rocq_int63::ltb(v0, v1)
}

// Rocq: Cold.cold_implem.bdec
pub fn bdec(b: bool) -> sumbool {
  if b {
    sumbool::left
  } else {
    sumbool::right
  }
}

// Rocq: Corelib.Numbers.Cyclic.Int63.PrimInt63.add
// Variant: uncurried
pub fn add(v0: u64, v1: u64) -> u64 {
  rocq_int63::add(v0, v1)
}

// Rocq: Corelib.Numbers.Cyclic.Int63.PrimInt63.ltsb
// Variant: uncurried
pub fn ltsb(v0: u64, v1: u64) -> bool {
  rocq_int63::ltsb(v0, v1)
}

// Rocq: Cold.cold_implem.count_loop
// Variant: uncurried
pub fn count_loop_1(x: Rc<Array<u64>>, n: u64, i: u64, acc: u64) -> u64 {
  count_loop(x, n, i, acc, ())
}

// Rocq: Cold.cold_implem.count_loop (local: count_loop)
// Variant: uncurried, lifted
pub fn count_loop(x: Rc<Array<u64>>, n: u64, i: u64, acc: u64, _H: ()) -> u64 {
  let tmp = ltb(i, n);
  match bdec(tmp) {
    sumbool::left => {
      let tmp_1 = add(i, 1u64);
      let tmp_2 = rocq_array::get::<u64>(&x, i);
      let tmp_3 = 0u64;
      let tmp_4 = if ltsb(tmp_2, tmp_3) {
        add(acc, 1u64)
      } else {
        acc
      };
      count_loop(x, n, tmp_1, tmp_4, ())
    },
    sumbool::right => {
      std::mem::drop(x);
      acc
    },
  }
}

// Rocq: Cold.cold_implem.count_negatives_impl
pub fn count_negatives_impl(x: Rc<Array<u64>>) -> u64 {
  let n = rocq_array::length::<u64>(&x);
  count_loop_1(x, n, 0u64, 0u64)
}
